// The Cloudflare binding types used by cloudflare-env.d.ts (generated by `npm run cf:typegen`), taken from
// @cloudflare/workers-types as plain imports: its global version would clash with the DOM types the UI uses.
import type * as CF from "@cloudflare/workers-types/index";

declare global {
  type D1Database = CF.D1Database;
  type D1PreparedStatement = CF.D1PreparedStatement;
  type R2Bucket = CF.R2Bucket;
  type R2ObjectBody = CF.R2ObjectBody;
  type VectorizeIndex = CF.VectorizeIndex;
  type Ai = CF.Ai;
  type Fetcher = CF.Fetcher;
}
